          import org.apache.log4j.Logger;

          import java.util.Map;
          import java.util.HashMap;

          Logger logger = Logger.getLogger("IAM_COE_BIRTHRIGHT_PROVISIONING");
          if (logger.isTraceEnabled()) {
          logger.trace("Alpha-Workflow-Immediate-Termination -> Entered to Send Joiner Emails Step (emailArgList Argument)!!!");
          }
          String CUSTOMOBJECTNAME = "Alpha-Custom-Termination Custom Object";
          Identity identityObject = context.getObjectByName(Identity.class,identityName);
          String emailTemplate = (String) getValueFromCustomObject(CUSTOMOBJECTNAME,"terminationSuccess_emailTemplate");
          logger.debug("Alpha-Workflow-Immediate-Termination - Send Joiner Emails (emailArgList Argument) -> EmailTemplate : "+emailTemplate);

          Map successEmailArgs = new HashMap();

          String emailTo = null;
          Identity validManager = null;  
          validManager = getValidManagerRecursive(context,identityObject,"spadmin");
          emailTo = validManager.getName();
          logger.debug("Alpha-Workflow-Immediate-Termination - Send Joiner Emails (emailArgList Argument) -> EmailTemplate : "+emailTo);

          successEmailArgs.put("to",emailTo);
          successEmailArgs.put("emailTemplate",emailTemplate);
          logger.debug("Alpha-Workflow-Immediate-Termination - Send Joiner Emails (emailArgList Argument) -> EmailArguments : "+successEmailArgs);

          if (identityObject != null) {
          logger.debug("Alpha-Workflow-Immediate-Termination - Send Joiner Emails (emailArgList Argument) -> Decaching identity object");
          context.decache(identityObject);
          }
          if (logger.isTraceEnabled()) {
          logger.trace("Alpha-Workflow-Immediate-Termination -> Send Joiner Emails Step (emailArgList Argument) Ended!!!");
          }
          return successEmailArgs;
